# ====================================================================================================
# pm_common
# ====================================================================================================
"""Shared helpers for the OCR-correction training pipeline (metrics, text normalisation, line fragments)."""

import hashlib
import random
import re

from rapidfuzz.distance import Levenshtein

# --------------------------------------------------------------------------- metrics
def edit_distance(a: str, b: str) -> int:
    return Levenshtein.distance(a, b)


def cer(preds: list[str], refs: list[str]) -> float:
    """Character error rate over a corpus: total edits / total reference characters."""
    if not refs:
        return 0.0
    edits = sum(edit_distance(p, r) for p, r in zip(preds, refs))
    return edits / max(sum(len(r) for r in refs), 1)


# --------------------------------------------------------------------------- text normalisation
_PUNCT_MAP = str.maketrans({"‘": "'", "’": "'", "“": '"', "”": '"', "–": "-", "—": "-", " ": " "})


def normalise(text: str) -> str:
    text = text.translate(_PUNCT_MAP)
    text = re.sub(r"\[\d+\]", "", text)  # [1] citations
    return re.sub(r"\s+", " ", text).strip()


def usable_sentence(s: str, lo: int = 30, hi: int = 260) -> bool:
    """Handwritten exam text: plain ASCII prose, no markup/URLs."""
    if not (lo <= len(s) <= hi) or not s.isascii():
        return False
    if re.search(r"https?://|[{}|=<>\\^~`@#]", s):
        return False
    letters = sum(c.isalpha() for c in s)
    return letters / len(s) > 0.65 and s[0].isalnum()


def split_sentences(text: str) -> list[str]:
    out = []
    for para in re.split(r"\n\s*\n|\n", text):
        for s in re.split(r"(?<=[.!?])\s+(?=[A-Z0-9(])", normalise(para)):
            if usable_sentence(s):
                out.append(s)
    return out


# --------------------------------------------------------------------------- group split
def group_bucket(group: str) -> int:
    """Deterministic 0-99 bucket for a sentence, so every line from one sentence lands in one split."""
    return int(hashlib.md5(group.lower().encode()).hexdigest(), 16) % 100


def split_of(group: str, val_pct: int = 5, test_pct: int = 5) -> str:
    b = group_bucket(group)
    if b < test_pct:
        return "test"
    if b < test_pct + val_pct:
        return "val"
    return "train"


# --------------------------------------------------------------------------- line fragments
_MARKERS = ["{n})", "{n} )", "{n}.", "Q{n}.", "Q{n})", "Ans {n}:", "({n})", "{n}-"]


def fragment(sentence: str, rng: random.Random, lo: int = 35, hi: int = 85) -> list[str]:
    """Cut a sentence into line-sized pieces at word boundaries.

    The backend corrects one *page line* at a time, and a student's sentence wraps across lines, so the model
    must be trained on line-sized fragments that start and end mid-sentence.
    """
    words = sentence.split()
    pieces, cur = [], ""
    width = rng.randint(lo, hi)
    for w in words:
        if cur and len(cur) + 1 + len(w) > width:
            pieces.append(cur)
            cur, width = w, rng.randint(lo, hi)
        else:
            cur = f"{cur} {w}".strip()
    if cur:
        if pieces and len(cur) < 12:  # avoid a one-word orphan line
            pieces[-1] += " " + cur
        else:
            pieces.append(cur)
    return pieces


def add_marker(line: str, rng: random.Random) -> str:
    n = rng.randint(1, 10)
    marker = rng.choice(_MARKERS).format(n=n)
    if rng.random() < 0.2:
        marker = f"({rng.choice('abcd')}) {marker}"
    return f"{marker} {line}"


def chunk_words(text: str, max_chars: int = 38) -> list[str]:
    """Split a line into segments the way the backend's detector does (bounded width) before TrOCR."""
    chunks, cur = [], ""
    for w in text.split():
        if cur and len(cur) + 1 + len(w) > max_chars:
            chunks.append(cur)
            cur = w
        else:
            cur = f"{cur} {w}".strip()
    return chunks + ([cur] if cur else [])


# --------------------------------------------------------------------------- fact swaps
# Fluent-but-wrong variants of a sentence. The correction model must repair OCR damage in such a sentence
# WITHOUT "fixing" the student's mistake, otherwise it would silently change what gets graded.
_SWAP_PAIRS = [
    ("Last In First Out", "First In First Out"), ("LIFO", "FIFO"), ("stack", "queue"), ("true", "false"),
    ("O(log n)", "O(n)"), ("public", "private"), ("compile-time", "run-time"), ("symmetric", "asymmetric"),
    ("supervised", "unsupervised"), ("overfitting", "underfitting"), ("precision", "recall"),
    ("inheritance", "composition"), ("minimum", "maximum"), ("encrypt", "decrypt"), ("sorted", "unsorted"),
    ("increase", "decrease"), ("before", "after"), ("Agile", "Waterfall"), ("white-box", "black-box"),
    ("public key", "private key"), ("synchronous", "asynchronous"), ("abstract", "concrete"),
]


def fact_swap(sentence: str) -> str | None:
    """Swap the first matching term for its opposite (case preserved); None if nothing matches."""
    for a, b in _SWAP_PAIRS:
        for x, y in ((a, b), (b, a)):
            m = re.search(rf"(?<![A-Za-z]){re.escape(x)}(?![A-Za-z])", sentence, re.I)
            if m:
                rep = y.capitalize() if m.group(0)[0].isupper() and not y[0].isupper() else y
                return sentence[: m.start()] + rep + sentence[m.end():]
    return None


# --------------------------------------------------------------------------- real handwriting sources
def iam_detok(text: str) -> str:
    """IAM transcripts are word-tokenised with '|' separators and detached punctuation; restore normal spacing."""
    t = text.replace("|", " ")
    t = re.sub(r"\s+([,.;:!?%)\]])", r"\1", t)
    t = re.sub(r"([(\[])\s+", r"\1", t)
    return re.sub(r"\s+", " ", t).strip()


def read_manifest(path: str) -> list[tuple[str, str]]:
    """TSV of  <image path relative to the manifest> TAB <transcript>  ->  [(absolute image path, transcript)]."""
    from pathlib import Path

    base = Path(path).resolve().parent
    out = []
    for line in Path(path).read_text(encoding="utf-8").splitlines():
        if not line.strip() or line.startswith("#"):
            continue
        img, _, text = line.partition("\t")
        if text.strip() and (base / img.strip()).exists():
            out.append((str(base / img.strip()), text.strip()))
    return out


def read_iam(iam_dir: str, limit: int = 0, seed: int = 0) -> list[tuple[str, str, str]]:
    """Official IAM database (lines.txt + line PNGs) -> [(image path, transcript, form id)]."""
    from pathlib import Path

    root = Path(iam_dir)
    lines_txt = next(iter(sorted(root.rglob("lines.txt"))), None)
    if lines_txt is None:
        raise FileNotFoundError(f"no lines.txt under {iam_dir} (extract ascii.tgz and lines.tgz of the IAM download there)")
    images = {p.stem: str(p) for p in root.rglob("*.png")}
    rows = []
    for line in lines_txt.read_text(encoding="utf-8", errors="replace").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        parts = line.split(None, 8)
        if len(parts) < 9 or parts[1] != "ok" or parts[0] not in images:
            continue
        text = iam_detok(parts[8])
        if 8 <= len(text) <= 120:
            rows.append((images[parts[0]], text, parts[0].rsplit("-", 1)[0]))
    random.Random(seed).shuffle(rows)
    return rows[:limit] if limit else rows

# ====================================================================================================
# pm_noise
# ====================================================================================================
"""Noise generators that turn clean text into TrOCR-like output.

1. ``simulate``   - fast character-level confusion model (no GPU / model needed).
2. ``TrOCRNoiser`` - renders text in handwriting-style fonts and runs the REAL TrOCR model, so the errors are
   the ones PaperMind's OCR stage actually makes.
"""

import math
import random
import re
from pathlib import Path


# --------------------------------------------------------------------------- 1. simulated confusions
CONFUSIONS = {
    "l": ["1", "I", "i", "!"], "I": ["l", "1", "i"], "1": ["l", "I", "i"], "0": ["O", "o", "D"], "O": ["0", "o", "Q"],
    "o": ["0", "a", "c"], "m": ["rn", "in", "nn"], "n": ["ri", "u", "h"], "a": ["o", "u", "d"], "e": ["c", "a", "o"],
    "g": ["q", "9", "y"], "q": ["g", "9"], "S": ["5", "s"], "s": ["5", "S", "r"], "Z": ["2", "z"], "z": ["2", "Z"],
    "B": ["8", "R"], "b": ["6", "h", "l"], "G": ["6", "C"], "h": ["b", "li", "n"], "d": ["cl", "a"], "u": ["n", "ii", "v"],
    "v": ["y", "u", "r"], "y": ["v", "g"], "c": ["e", "o", "r"], "t": ["f", "l", "+"], "f": ["t", "s"], "r": ["n", "v", "i"],
    "w": ["vv", "uu"], "k": ["h", "lc"], "i": ["l", "j", "e"], "p": ["P", "b"], "x": ["n", "k"], "H": ["N", "M"],
    "T": ["I", "F"], "U": ["V", "O"], "W": ["V", "N"], "E": ["F", "C"],
}
_PUNCT_SPACE = re.compile(r"([.,:;!?()])")


def simulate(text: str, level: float, rng: random.Random) -> str:
    """Return a noisy version of ``text``. ``level`` in [0, 1]; 0 returns the text unchanged."""
    if level <= 0:
        return text
    out: list[str] = []
    for ch in text:
        r = rng.random()
        if ch in CONFUSIONS and r < level * 0.22:
            out.append(rng.choice(CONFUSIONS[ch]))
        elif ch != " " and r > 1 - level * 0.035:
            continue  # dropped stroke
        elif ch.isalpha() and rng.random() < level * 0.015:
            out.append(ch + ch)  # doubled stroke
        else:
            out.append(ch)
    noisy = "".join(out)

    # TrOCR habit: detached punctuation ("Liskov . principle", "2 ) False")
    if rng.random() < 0.25 + level * 0.5:
        noisy = _PUNCT_SPACE.sub(lambda m: f" {m.group(1)} " if rng.random() < 0.55 else m.group(1), noisy)
    # split / merged words
    words = noisy.split(" ")
    for i in range(len(words)):
        if len(words[i]) > 6 and rng.random() < level * 0.05:
            k = rng.randint(2, len(words[i]) - 2)
            words[i] = words[i][:k] + " " + words[i][k:]
        elif i + 1 < len(words) and rng.random() < level * 0.03:
            words[i] = words[i] + words[i + 1]
            words[i + 1] = ""
    noisy = re.sub(r" {2,}", " ", " ".join(words)).strip()
    # mangled leading question number, e.g. "1) (b)" -> "19 ( 0b ) ."
    if re.match(r"^\(?[A-Za-z]{0,3}\d{1,2}\s*[\.\):\-]", noisy) and rng.random() < level * 0.35:
        noisy = re.sub(r"^(\(?[A-Za-z]{0,3})(\d{1,2})\s*([\.\):\-])", lambda m: f"{m.group(1)}{m.group(2)}{rng.choice(['9', '0', ' ', ''])} {m.group(3)} ", noisy, 1)
        noisy = re.sub(r" {2,}", " ", noisy).strip()
    return noisy


# --------------------------------------------------------------------------- 2. real TrOCR noise
MAX_SEGMENT_ASPECT = 6.5  # same bound the backend's line detector uses before TrOCR


def split_wide(img, max_aspect: float = MAX_SEGMENT_ASPECT):
    """Cut a wide line image at its emptiest columns so each piece has aspect <= max_aspect (as production does)."""
    import numpy as np

    w, h = img.size
    if w / max(h, 1) <= max_aspect:
        return [img]
    gray = np.asarray(img.convert("L"), dtype=np.float32)
    ink = (gray < gray.mean() - 0.5 * gray.std()).sum(axis=0).astype(float)
    ink = np.convolve(ink, np.ones(5) / 5, mode="same")
    max_w = int(max_aspect * h)
    cuts, start = [0], 0
    while w - start > max_w:
        lo, hi = start + int(max_w * 0.55), start + max_w
        cut = lo + int(np.argmin(ink[lo:hi]))
        cuts.append(cut)
        start = cut
    cuts.append(w)
    return [img.crop((a, 0, b, h)) for a, b in zip(cuts[:-1], cuts[1:]) if b - a > 4]


def augment(img, rng: random.Random):
    """Light photo-like variation so repeated passes over the same real line give different TrOCR errors."""
    import numpy as np
    from PIL import Image, ImageEnhance, ImageFilter

    img = img.convert("RGB")
    if rng.random() < 0.7:
        img = img.rotate(rng.uniform(-2.0, 2.0), fillcolor=(255, 255, 255), resample=Image.BICUBIC, expand=True)
    img = ImageEnhance.Contrast(img).enhance(rng.uniform(0.7, 1.3))
    img = ImageEnhance.Brightness(img).enhance(rng.uniform(0.85, 1.15))
    if rng.random() < 0.5:
        img = img.filter(ImageFilter.GaussianBlur(rng.uniform(0.3, 1.2)))
    if rng.random() < 0.4:
        arr = np.asarray(img, dtype=np.float32) + np.random.normal(0, rng.uniform(2, 10), (img.size[1], img.size[0], 3))
        img = Image.fromarray(np.clip(arr, 0, 255).astype("uint8"))
    return img
def find_fonts(font_dir: str | None) -> list[str]:
    paths: list[str] = []
    if font_dir and Path(font_dir).is_dir():
        paths += [str(p) for p in sorted(Path(font_dir).glob("*")) if p.suffix.lower() in (".ttf", ".otf")]
    for p in ("C:/Windows/Fonts/Inkfree.ttf", "C:/Windows/Fonts/segoesc.ttf", "C:/Windows/Fonts/LHANDW.TTF",
              "C:/Windows/Fonts/BRUSHSCI.TTF"):
        if Path(p).exists():
            paths.append(p)
    return paths


def render_segment(text: str, font_path: str, rng: random.Random):
    """Draw a text segment word by word with jitter so it looks hand-written rather than typeset."""
    import numpy as np
    from PIL import Image, ImageDraw, ImageFilter, ImageFont

    size = rng.randint(34, 58)
    font = ImageFont.truetype(font_path, size)
    pad = int(size * 0.5)
    words = text.split(" ")
    advances = [font.getlength(w + " ") * rng.uniform(0.92, 1.12) for w in words]
    width = int(sum(advances)) + 2 * pad
    height = int(size * 1.9)
    img = Image.new("RGB", (width, height), (rng.randint(235, 255),) * 3)
    d = ImageDraw.Draw(img)
    ink = (rng.randint(0, 50), rng.randint(0, 50), rng.randint(20, 110))
    x = float(pad)
    for w, adv in zip(words, advances):
        d.text((x, pad * 0.6 + rng.uniform(-3, 3)), w, font=font, fill=ink)
        x += adv
    if rng.random() < 0.7:
        img = img.rotate(rng.uniform(-2.5, 2.5), fillcolor=(255, 255, 255), resample=Image.BICUBIC)
    if rng.random() < 0.5:
        img = img.filter(ImageFilter.GaussianBlur(rng.uniform(0.3, 1.3)))
    if rng.random() < 0.5:
        arr = np.asarray(img, dtype=np.float32) + np.random.normal(0, rng.uniform(2, 14), (height, width, 3))
        img = Image.fromarray(np.clip(arr, 0, 255).astype("uint8"))
    return img


class TrOCRNoiser:
    MODEL = "microsoft/trocr-base-handwritten"

    def __init__(self, fonts: list[str], seed: int = 0, batch_size: int = 64, model: str | None = None):
        import torch
        from transformers import TrOCRProcessor, VisionEncoderDecoderModel

        if not fonts:
            raise RuntimeError("TrOCR noise needs at least one handwriting-style font (see --font-dir).")
        self.fonts, self.rng, self.batch_size = fonts, random.Random(seed), batch_size
        self.torch = torch
        self.processor = TrOCRProcessor.from_pretrained(model or self.MODEL)
        self.model = VisionEncoderDecoderModel.from_pretrained(model or self.MODEL).eval()
        self.device = "cuda" if torch.cuda.is_available() else "cpu"
        self.model.to(self.device)

    def read_lines(self, lines: list[str]) -> list[tuple[str, float]]:
        """Render each line as bounded-width segments (like the production detector), OCR them, re-join."""
        segs: list[tuple[int, str]] = []
        for i, line in enumerate(lines):
            font = self.rng.choice(self.fonts)  # one font per line, as one writer writes one line
            for chunk in chunk_words(line):
                segs.append((i, chunk, font))
        texts: list[tuple[str, float]] = []
        order = sorted(range(len(segs)), key=lambda k: len(segs[k][1]))  # similar widths batch together
        results: dict[int, tuple[str, float]] = {}
        for s in range(0, len(order), self.batch_size):
            idx = order[s : s + self.batch_size]
            imgs = [render_segment(segs[k][1], segs[k][2], self.rng) for k in idx]
            for k, res in zip(idx, self._ocr(imgs)):
                results[k] = res
        joined: dict[int, list[tuple[str, float]]] = {}
        for k, (i, _chunk, _font) in enumerate(segs):
            joined.setdefault(i, []).append(results[k])
        for i in range(len(lines)):
            parts = joined.get(i, [])
            text = " ".join(t for t, _ in parts).strip()
            conf = sum(c for _, c in parts) / max(len(parts), 1)
            texts.append((text, conf))
        return texts

    def read_images(self, paths: list[str], augment_images: bool = False) -> list[tuple[str, float]]:
        """OCR REAL line photos/scans (IAM, your own pages): bounded-width segments -> TrOCR -> re-join."""
        from PIL import Image, ImageOps

        segs = []
        for i, path in enumerate(paths):
            img = ImageOps.exif_transpose(Image.open(path)).convert("RGB")
            if augment_images:
                img = augment(img, self.rng)
            segs += [(i, piece) for piece in split_wide(img)]
            if i % 2000 == 0:
                print(f"  loading real images {i:,}/{len(paths):,}", flush=True)
        order = sorted(range(len(segs)), key=lambda k: segs[k][1].size[0])
        results = {}
        total = len(order)
        for s in range(0, total, self.batch_size):
            idx = order[s : s + self.batch_size]
            for k, res in zip(idx, self._ocr([segs[k][1] for k in idx])):
                results[k] = res
            if (s // self.batch_size) % 40 == 0:
                print(f"  OCR real segments {min(s + self.batch_size, total):,}/{total:,}", flush=True)
        grouped = {}
        for k, (i, _) in enumerate(segs):
            grouped.setdefault(i, []).append(results[k])
        out = []
        for i in range(len(paths)):
            parts = grouped.get(i, [])
            out.append((" ".join(t for t, _ in parts).strip(), sum(c for _, c in parts) / max(len(parts), 1)))
        return out

    def _ocr(self, images) -> list[tuple[str, float]]:
        torch = self.torch
        with torch.inference_mode():
            pixels = self.processor(images=images, return_tensors="pt").pixel_values.to(self.device)
            out = self.model.generate(pixels, max_new_tokens=64, num_beams=1, output_scores=True, return_dict_in_generate=True)
            lp = self.model.compute_transition_scores(out.sequences, out.scores, normalize_logits=True)
            tokens = out.sequences[:, 1:]
            pad = self.processor.tokenizer.pad_token_id
            texts = self.processor.batch_decode(out.sequences, skip_special_tokens=True)
        res = []
        for t, l, tok in zip(texts, lp, tokens):
            mask = tok != pad
            res.append((t.strip(), math.exp(float(l[mask].mean())) if mask.any() else 0.0))
        return res

# ====================================================================================================
# evaluate_correction
# ====================================================================================================
#!/usr/bin/env python3
"""Evaluate an OCR-correction checkpoint on held-out sentences.

    python evaluate_correction.py --model /path/to/checkpoint --data data            # reads data/test.jsonl
    python evaluate_correction.py --model google/byt5-small --data data --limit 200   # an untrained model, for comparison

Reports, per noise source and overall:
  CER before / after correction   - did the model reduce character errors? (lower is better)
  exact match                     - lines corrected perfectly
  over-correction                 - lines that were ALREADY correct and got changed (must be ~0)
  preservation (fact-swapped)     - on fluent-but-wrong student sentences, how often the model rewrote the mistake
                                    back to the true statement. This is the grading-safety metric: a correction
                                    model must repair handwriting errors, never the student's content.
"""

import argparse
import json
import sys
from pathlib import Path



def load_jsonl(path: Path, limit: int = 0) -> list[dict]:
    rows = [json.loads(l) for l in path.read_text(encoding="utf-8").splitlines() if l.strip()]
    return rows[:limit] if limit else rows


def correct_texts(model, tok, texts: list[str], batch_size: int = 64, beams: int = 1, max_len: int = 192) -> list[str]:
    import torch

    device = next(model.parameters()).device
    order = sorted(range(len(texts)), key=lambda i: len(texts[i]))
    out = [""] * len(texts)
    model.eval()
    with torch.inference_mode():
        for s in range(0, len(order), batch_size):
            idx = order[s : s + batch_size]
            enc = tok([texts[i] for i in idx], return_tensors="pt", padding=True, truncation=True, max_length=max_len).to(device)
            gen = model.generate(**enc, max_new_tokens=max_len, num_beams=beams)
            for i, t in zip(idx, tok.batch_decode(gen, skip_special_tokens=True)):
                out[i] = t.strip()
    return out


def score(rows: list[dict], preds: list[str]) -> dict:
    ins, refs = [r["input"] for r in rows], [r["target"] for r in rows]
    report: dict = {"lines": len(rows)}

    def block(sel: list[int]) -> dict:
        if not sel:
            return {}
        i_, r_, p_ = [ins[k] for k in sel], [refs[k] for k in sel], [preds[k] for k in sel]
        return {
            "lines": len(sel),
            "cer_before": round(cer(i_, r_), 4),
            "cer_after": round(cer(p_, r_), 4),
            "exact_before": round(sum(a == b for a, b in zip(i_, r_)) / len(sel), 4),
            "exact_after": round(sum(a == b for a, b in zip(p_, r_)) / len(sel), 4),
        }

    report["overall"] = block(list(range(len(rows))))
    for src in sorted({r["source"] for r in rows}):
        report[f"source_{src}"] = block([k for k, r in enumerate(rows) if r["source"] == src])

    clean = [k for k in range(len(rows)) if ins[k] == refs[k]]
    if clean:
        report["over_correction"] = {
            "already_correct_lines": len(clean),
            "changed_by_model": sum(preds[k] != ins[k] for k in clean),
            "rate": round(sum(preds[k] != ins[k] for k in clean) / len(clean), 4),
        }

    swapped = [k for k, r in enumerate(rows) if r.get("kind") == "swapped" and r.get("orig") and ins[k] != refs[k]]
    if swapped:
        # reverted = the model's output is closer to the TRUE sentence's wording than to what the student wrote
        reverted = 0
        for k in swapped:
            true_frag = rows[k]["orig"]
            if edit_distance(preds[k], refs[k]) > 0 and preds[k] and edit_distance(preds[k], true_frag) < edit_distance(preds[k], refs[k]):
                reverted += 1
        report["preservation"] = {**block(swapped), "rewritten_to_true_fact": reverted, "rate": round(reverted / len(swapped), 4)}
    return report


def _main_eval(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter, allow_abbrev=False)
    ap.add_argument("--model", required=True, help="checkpoint dir or HF id")
    ap.add_argument("--data", default="data", help="folder containing <split>.jsonl")
    ap.add_argument("--split", default="test")
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--beams", type=int, default=1)
    ap.add_argument("--batch", type=int, default=64)
    ap.add_argument("--report", default=None, help="write the JSON report here")
    args, _ignored = ap.parse_known_args(argv)

    import torch
    from transformers import AutoModelForSeq2SeqLM, AutoTokenizer

    rows = load_jsonl(Path(args.data) / f"{args.split}.jsonl", args.limit)
    tok = AutoTokenizer.from_pretrained(args.model)
    model = AutoModelForSeq2SeqLM.from_pretrained(args.model)
    if torch.cuda.is_available():
        model.to("cuda")
    preds = correct_texts(model, tok, [r["input"] for r in rows], args.batch, args.beams)
    report = score(rows, preds)
    print(json.dumps(report, indent=2))

    worst = sorted(range(len(rows)), key=lambda k: -edit_distance(preds[k], rows[k]["target"]))[:8]
    print("\nWorst remaining errors (input | prediction | target):")
    for k in worst:
        print(f"  {rows[k]['input']!r}\n   -> {preds[k]!r}\n   == {rows[k]['target']!r}")
    if args.report:
        Path(args.report).write_text(json.dumps(report, indent=2))
    return 0



# ====================================================================================================
# build_dataset
# ====================================================================================================
#!/usr/bin/env python3
"""Build the OCR-correction dataset: (noisy TrOCR-style line  ->  clean line) pairs, as JSONL.

Differences from the first generator, each fixing a real weakness:
  * thousands of DISTINCT sentences (built-in seeds + Simple-English Wikipedia filtered to CS topics + your own
    syllabus / textbook / student-answer files) instead of ~20 repeated ones;
  * splits are made by SENTENCE, so test sentences are never seen in training (no memorisation-inflated scores);
  * examples are line-sized fragments (a wrapped sentence), because the backend corrects one page line at a time;
  * noise comes from the REAL TrOCR model on handwriting-style fonts (--trocr-frac) plus a fast simulated model;
  * REAL handwriting can be added: the official IAM database (--iam-dir) and/or your own scanned lines (--manifest);
    --test-manifest keeps your own real pages out of training so they give an honest real-world test score;
  * "fact-swapped" sentences (stack<->queue, LIFO<->FIFO ...) are included as targets, so the model learns to repair
    OCR damage WITHOUT correcting a student's factual mistakes (that would silently change grades).

    python build_dataset.py --out data --n-lines 50000 --font-dir fonts --trocr-frac 0.35
    python build_dataset.py --out /tmp/smoke --n-lines 300 --wiki-n 0 --trocr-frac 0     # tiny, no network/GPU
"""

import argparse
import json
import random
import statistics
import sys
import time
from collections import Counter
from pathlib import Path



# Phrases that are specific to computing; ambiguous single words ("python", "web", "code", "memory") are left out.
WIKI_KEYWORDS = (
    "algorithm", "data structure", "software", "computer program", "programming language", "database", "computer network",
    "encrypt", "cryptograph", "cybersecurity", "computer security", "machine learning", "neural network",
    "artificial intelligence", "object-oriented", "compiler", "operating system", "source code", "sorting",
    "network protocol", "microprocessor", "computer memory", "hash function", "recursion", "firewall", "web server",
    "software development", "computer science",
)


def load_seed() -> list[str]:
    return list(SEED_SENTENCES)


def load_files(paths: list[str]) -> list[str]:
    out: list[str] = []
    for p in paths:
        path = Path(p)
        if path.suffix.lower() == ".pdf":
            import fitz  # PyMuPDF

            with fitz.open(path) as doc:
                text = "\n".join(page.get_text("text") for page in doc)
        else:
            text = path.read_text(encoding="utf-8", errors="replace")
        out += split_sentences(text)
    return out


def load_wiki(n: int, seed: int) -> list[str]:
    """Stream Simple-English Wikipedia and keep prose sentences about computing."""
    if n <= 0:
        return []
    out: list[str] = []
    try:
        from datasets import load_dataset

        ds = load_dataset("wikimedia/wikipedia", "20231101.simple", split="train", streaming=True)
        ds = ds.shuffle(seed=seed, buffer_size=2000)
        for row in ds:
            for s in split_sentences(row["text"]):
                if any(k in s.lower() for k in WIKI_KEYWORDS):
                    out.append(s)
            if len(out) >= n:
                break
    except Exception as exc:  # no internet (e.g. Kaggle with internet off) - carry on with the other sources
        print(f"WARNING: could not read Wikipedia ({type(exc).__name__}: {exc}); continuing without it", file=sys.stderr)
    return out[:n]


def _main_build(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter, allow_abbrev=False)
    ap.add_argument("--out", default="data")
    ap.add_argument("--n-lines", type=int, default=50_000, help="total examples to produce")
    ap.add_argument("--wiki-n", type=int, default=15_000, help="sentences to pull from Simple Wikipedia (0 = skip)")
    ap.add_argument("--files", nargs="*", default=[], help="extra .txt/.md/.pdf (syllabus, textbooks, student answers)")
    ap.add_argument("--font-dir", default=None, help="folder of handwriting-style .ttf/.otf fonts")
    ap.add_argument("--trocr-frac", type=float, default=0.35, help="share of examples noised by the real TrOCR model")
    ap.add_argument("--trocr-batch", type=int, default=64)
    ap.add_argument("--clean-frac", type=float, default=0.10, help="share of unchanged lines (anti over-correction)")
    ap.add_argument("--swap-frac", type=float, default=0.15, help="share of sentences also added as fact-swapped")
    ap.add_argument("--marker-frac", type=float, default=0.55)
    ap.add_argument("--iam-dir", default=None, help="folder with the official IAM lines.txt + line PNGs (real handwriting)")
    ap.add_argument("--iam-lines", type=int, default=8000, help="how many IAM lines to add")
    ap.add_argument("--iam-repeat", type=int, default=1, help="augmented passes over each IAM line (more real-handwriting errors)")
    ap.add_argument("--manifest", default=None, help="TSV 'image<TAB>transcript' of your own real line images (trained on)")
    ap.add_argument("--manifest-repeat", type=int, default=4, help="augmented passes over each manifest line")
    ap.add_argument("--test-manifest", default=None, help="TSV of real lines used ONLY for the test split (honest real-world score)")
    ap.add_argument("--seed", type=int, default=42)
    args, _ignored = ap.parse_known_args(argv)  # tolerate options that belong to the training stage
    rng = random.Random(args.seed)
    t0 = time.time()

    seed_sentences = [normalise(s) for s in load_seed()]
    # A fixed quarter of the hand-written seed sentences is reserved for the TEST split (never trained on). They are
    # in-domain exam text, and their fact-swapped variants form the "does the model leave student errors alone" test.
    held_out = set(seed_sentences[::4])
    sentences = seed_sentences + [normalise(s) for s in load_files(args.files) + load_wiki(args.wiki_n, args.seed)]
    sentences = list(dict.fromkeys(sentences))
    rng.shuffle(sentences)
    print(f"{len(sentences):,} distinct sentences ({time.time() - t0:.0f}s)")
    if len(sentences) < 200:
        print("WARNING: very small corpus - the model will memorise it. Use --wiki-n and/or --files.", file=sys.stderr)

    # ---- 1. clean fragments, grouped by their source sentence ---------------------------------------------
    rows: list[dict] = []
    seed_set = set(seed_sentences)
    si = 0
    while len(rows) < args.n_lines:
        sent = sentences[si % len(sentences)]
        si += 1
        variants = [(sent, "normal", None)]
        wanted = sent in held_out or (sent in seed_set and rng.random() < 0.8) or rng.random() < args.swap_frac
        swapped = fact_swap(sent) if wanted else None
        if swapped:
            variants.append((swapped, "swapped", sent))
        for text, kind, orig in variants:
            for j, frag in enumerate(fragment(text, rng)):
                if j == 0 and rng.random() < args.marker_frac:
                    frag = add_marker(frag, rng)
                rows.append({"target": frag, "group": sent, "kind": kind, "orig": orig})
    rows = rows[: args.n_lines]
    if si > len(sentences):
        print(f"note: corpus reused {si / len(sentences):.1f}x to reach {args.n_lines:,} lines")

    # ---- 2. choose a noise source for each line ------------------------------------------------------------
    for r in rows:
        x = rng.random()
        r["source"] = "clean" if x < args.clean_frac else ("trocr" if x < args.clean_frac + args.trocr_frac else "sim")

    trocr_rows = [r for r in rows if r["source"] == "trocr"]
    if trocr_rows:
        fonts = find_fonts(args.font_dir)
        if not fonts:
            print("WARNING: no fonts found - falling back to simulated noise for the TrOCR share", file=sys.stderr)
            for r in trocr_rows:
                r["source"] = "sim"
        else:
            print(f"Running real TrOCR on {len(trocr_rows):,} rendered lines with {len(fonts)} font(s)...")
            noiser = TrOCRNoiser(fonts, seed=args.seed, batch_size=args.trocr_batch)
            for s in range(0, len(trocr_rows), 2000):
                part = trocr_rows[s : s + 2000]
                for r, (text, conf) in zip(part, noiser.read_lines([p["target"] for p in part])):
                    r["input"], r["trocr_conf"] = text, round(conf, 4)
                print(f"  TrOCR {min(s + 2000, len(trocr_rows)):,}/{len(trocr_rows):,} ({time.time() - t0:.0f}s)")
            del noiser

    levels = [0.15, 0.3, 0.45, 0.6, 0.8, 1.0]
    for r in rows:
        if r["source"] == "clean":
            r["input"] = r["target"]
        elif r["source"] == "sim":
            r["input"] = simulate(r["target"], rng.choice(levels), rng)
        r["input"] = r["input"].strip() or r["target"]
        r["edits"] = edit_distance(r["input"], r["target"])

    # ---- 2b. REAL handwriting (IAM, your own pages): OCR the actual images -------------------------------------
    real_jobs = []  # (image, transcript, group, source, test_only)
    if args.iam_dir:
        iam = read_iam(args.iam_dir, args.iam_lines, args.seed)
        print(f"IAM: {len(iam):,} usable lines")
        for _ in range(max(1, args.iam_repeat)):
            real_jobs += [(img, text, f"iam:{form}", "iam", False) for img, text, form in iam]
    if args.manifest:
        for _ in range(args.manifest_repeat):
            real_jobs += [(img, text, f"own:{text}", "own", False) for img, text in read_manifest(args.manifest)]
    if args.test_manifest:
        real_jobs += [(img, text, f"owntest:{text}", "own_test", True) for img, text in read_manifest(args.test_manifest)]
    forced_test_groups = set()
    if real_jobs:
        print(f"Running real TrOCR on {len(real_jobs):,} REAL handwriting lines...")
        noiser = TrOCRNoiser(["unused"], seed=args.seed, batch_size=args.trocr_batch)
        # augmented, so repeated passes over the same image give different errors
        outs = noiser.read_images([j[0] for j in real_jobs], augment_images=True)
        for (img, text, group, source, test_only), (ocr_text, conf) in zip(real_jobs, outs):
            if not ocr_text:
                continue
            rows.append({"target": text, "input": ocr_text, "group": group, "kind": "normal", "orig": None,
                         "source": source, "trocr_conf": round(conf, 4), "edits": edit_distance(ocr_text, text)})
            if test_only:
                forced_test_groups.add(group)
        del noiser

    # ---- 3. split by sentence group & write -----------------------------------------------------------------
    out = Path(args.out)
    out.mkdir(parents=True, exist_ok=True)
    splits: dict[str, list[dict]] = {"train": [], "val": [], "test": []}
    for r in rows:
        splits["test" if (r["group"] in held_out or r["group"] in forced_test_groups) else split_of(r["group"])].append(r)
    for name, part in splits.items():
        rng.shuffle(part)
        with (out / f"{name}.jsonl").open("w", encoding="utf-8") as f:
            for r in part:
                f.write(json.dumps(r, ensure_ascii=False) + "\n")

    test_groups, train_groups = {r["group"] for r in splits["test"]}, {r["group"] for r in splits["train"]}
    assert not (test_groups & train_groups), "split leak: a sentence is in both train and test"
    stats = {
        "lines": {k: len(v) for k, v in splits.items()},
        "distinct_sentences": len(sentences),
        "sources": dict(Counter(r["source"] for r in rows)),
        "kinds": dict(Counter(r["kind"] for r in rows)),
        "unchanged_pct": round(100 * sum(r["edits"] == 0 for r in rows) / len(rows), 1),
        "median_edits_changed": statistics.median([r["edits"] for r in rows if r["edits"]] or [0]),
        "baseline_cer": round(sum(r["edits"] for r in rows) / sum(len(r["target"]) for r in rows), 4),
        "seconds": round(time.time() - t0),
    }
    (out / "stats.json").write_text(json.dumps(stats, indent=2))
    print(json.dumps(stats, indent=2))
    print("\nSamples (input -> target):")
    for r in rng.sample(rows, min(8, len(rows))):
        print(f"  [{r['source']:5}/{r['kind']}] {r['input']!r}\n        -> {r['target']!r}")
    return 0



# ====================================================================================================
# train
# ====================================================================================================
#!/usr/bin/env python3
"""Fine-tune ByT5 to repair TrOCR errors. Works on Colab (A100) and, for smoke tests, on CPU.

    python train.py --data data --out ckpt --model google/byt5-base --epochs 4 --bs 64
    python train.py --data /tmp/smoke --out /tmp/ck --model google/byt5-small --max-steps 20 --bs 8   # smoke test

Design notes
  * NO version pins: it uses whatever transformers/torch Colab already has (pinning old tokenizers/transformers is
    what made the previous notebook hang while compiling Rust wheels). Version differences in Trainer arguments are
    handled below.
  * Weights stay in fp32 and bf16 is used for autocast only. Loading the model in pure bf16 loses small AdamW
    updates and trains noticeably worse.
  * Model selection is by validation CER of generated text, on sentences the model never trained on.
"""

import argparse
import inspect
import json
import sys
import time
from pathlib import Path



def make_portable(ckpt: Path) -> None:
    """Make a checkpoint written by a NEW transformers (Colab) loadable by older ones (the backend's 4.x).

    ByT5 keeps a separate output layer (lm_head.weight), but newer versions write tie_word_embeddings=true, which makes an
    older version overwrite it with the input embeddings -> gibberish output. They also write the extra-token list twice,
    which older tokenizers reject.
    """
    cfg_path, tok_path = Path(ckpt) / "config.json", Path(ckpt) / "tokenizer_config.json"
    if cfg_path.exists():
        cfg = json.loads(cfg_path.read_text(encoding="utf-8"))
        if cfg.get("tie_word_embeddings") is not False:
            cfg["tie_word_embeddings"] = False
            cfg_path.write_text(json.dumps(cfg, indent=2), encoding="utf-8")
    if tok_path.exists():
        tcfg = json.loads(tok_path.read_text(encoding="utf-8"))
        if isinstance(tcfg.get("extra_special_tokens"), list) and tcfg.get("extra_special_tokens") == tcfg.get("additional_special_tokens"):
            del tcfg["extra_special_tokens"]
            tok_path.write_text(json.dumps(tcfg, indent=2, ensure_ascii=False), encoding="utf-8")


def _main_train(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter, allow_abbrev=False)
    ap.add_argument("--data", default="data")
    ap.add_argument("--out", default="ckpt")
    ap.add_argument("--model", default="google/byt5-base")
    ap.add_argument("--epochs", type=float, default=4)
    ap.add_argument("--bs", type=int, default=64)
    ap.add_argument("--grad-accum", type=int, default=1, help="effective batch = bs * grad-accum (use for byt5-large)")
    ap.add_argument("--patience", type=int, default=2, help="stop after this many epochs without validation improvement (0 = off)")
    ap.add_argument("--eval-bs", type=int, default=128)
    ap.add_argument("--lr", type=float, default=2e-4)
    ap.add_argument("--warmup", type=float, default=0.05, help="fraction of steps")
    ap.add_argument("--max-len", type=int, default=192, help="bytes; lines are <~120 characters")
    ap.add_argument("--max-steps", type=int, default=-1, help="stop early (smoke test)")
    ap.add_argument("--val-limit", type=int, default=2000, help="validation lines used for model selection")
    ap.add_argument("--seed", type=int, default=42)
    args, _ignored = ap.parse_known_args(argv)  # tolerate options that belong to the data stage

    import numpy as np
    import torch
    from datasets import Dataset
    from transformers import (AutoModelForSeq2SeqLM, AutoTokenizer, DataCollatorForSeq2Seq, EarlyStoppingCallback,
                              Seq2SeqTrainer, Seq2SeqTrainingArguments, set_seed)

    set_seed(args.seed)
    cuda = torch.cuda.is_available()
    print(f"device: {'cuda ' + torch.cuda.get_device_name(0) if cuda else 'cpu'}")
    if cuda and not torch.cuda.is_bf16_supported():
        print("NOTE: this GPU has no bf16 (T4/P100): training runs in fp32 (fp16 is unstable for ByT5), so use byt5-small or expect it to be slow.")

    data = Path(args.data)
    train_rows, val_rows = load_jsonl(data / "train.jsonl"), load_jsonl(data / "val.jsonl", args.val_limit)
    print(f"train={len(train_rows):,}  val={len(val_rows):,}")

    tok = AutoTokenizer.from_pretrained(args.model)

    def encode(batch):
        enc = tok(batch["input"], max_length=args.max_len, truncation=True)
        enc["labels"] = tok(text_target=batch["target"], max_length=args.max_len, truncation=True)["input_ids"]
        return enc

    def to_ds(rows):
        ds = Dataset.from_dict({"input": [r["input"] for r in rows], "target": [r["target"] for r in rows]})
        return ds.map(encode, batched=True, remove_columns=["input", "target"])

    train_ds, val_ds = to_ds(train_rows), to_ds(val_rows)
    model = AutoModelForSeq2SeqLM.from_pretrained(args.model)  # fp32 master weights
    print(f"model: {args.model}  {sum(p.numel() for p in model.parameters()) / 1e6:.0f}M params")

    def compute_metrics(pred):
        preds, labels = pred
        preds = preds[0] if isinstance(preds, tuple) else preds
        preds = np.where(preds != -100, preds, tok.pad_token_id)
        labels = np.where(labels != -100, labels, tok.pad_token_id)
        p = [s.strip() for s in tok.batch_decode(preds, skip_special_tokens=True)]
        r = [s.strip() for s in tok.batch_decode(labels, skip_special_tokens=True)]
        return {"cer": round(cer(p, r), 5), "exact": round(sum(a == b for a, b in zip(p, r)) / len(r), 4)}

    # ---- Trainer argument names differ between transformers releases ----------------------------------
    # (v5 removed warmup_ratio, so compute an explicit number of warmup steps that every version accepts)
    steps_per_epoch = max(1, -(-len(train_ds) // (args.bs * args.grad_accum)))
    total_steps = args.max_steps if args.max_steps > 0 else int(steps_per_epoch * args.epochs)
    warmup_steps = max(1, int(total_steps * args.warmup))
    print(f"steps/epoch={steps_per_epoch}  total={total_steps}  warmup={warmup_steps}")
    ta = inspect.signature(Seq2SeqTrainingArguments.__init__).parameters
    tr = inspect.signature(Seq2SeqTrainer.__init__).parameters
    kwargs = dict(
        output_dir=args.out, num_train_epochs=args.epochs, max_steps=args.max_steps,
        per_device_train_batch_size=args.bs, per_device_eval_batch_size=args.eval_bs, gradient_accumulation_steps=args.grad_accum,
        learning_rate=args.lr, lr_scheduler_type="cosine", warmup_steps=warmup_steps, weight_decay=0.01,
        predict_with_generate=True, generation_max_length=args.max_len,
        save_strategy="epoch" if args.max_steps < 0 else "no", save_total_limit=2,
        load_best_model_at_end=args.max_steps < 0, metric_for_best_model="cer", greater_is_better=False,
        bf16=cuda and torch.cuda.is_bf16_supported(), logging_steps=50, report_to="none", seed=args.seed,
        dataloader_num_workers=2 if cuda else 0,
    )
    kwargs["eval_strategy" if "eval_strategy" in ta else "evaluation_strategy"] = "epoch" if args.max_steps < 0 else "no"
    dropped = [k for k in kwargs if k not in ta]  # an argument this transformers version doesn't know: skip, don't crash
    if dropped:
        print(f"note: ignoring unsupported TrainingArguments {dropped}")
        kwargs = {k: v for k, v in kwargs.items() if k in ta}
    trainer_kwargs = dict(model=model, args=Seq2SeqTrainingArguments(**kwargs), train_dataset=train_ds, eval_dataset=val_ds,
                          data_collator=DataCollatorForSeq2Seq(tok, model=model, padding=True, pad_to_multiple_of=8),
                          compute_metrics=compute_metrics)
    trainer_kwargs["processing_class" if "processing_class" in tr else "tokenizer"] = tok
    if args.patience > 0 and args.max_steps < 0:
        trainer_kwargs["callbacks"] = [EarlyStoppingCallback(early_stopping_patience=args.patience)]
    trainer = Seq2SeqTrainer(**trainer_kwargs)

    # Resume automatically if an earlier run in this folder was interrupted (disconnect, quota, closed laptop).
    last_ckpt = None
    if args.max_steps < 0 and Path(args.out).is_dir():
        from transformers.trainer_utils import get_last_checkpoint

        last_ckpt = get_last_checkpoint(args.out)
        if last_ckpt:
            print(f"resuming from {last_ckpt}")
    t0 = time.time()
    result = trainer.train(resume_from_checkpoint=last_ckpt)
    print(f"\ntrained in {(time.time() - t0) / 60:.1f} min  {result.metrics}")

    out = Path(args.out)
    trainer.save_model(str(out))
    tok.save_pretrained(str(out))
    make_portable(out)

    # ---- held-out test report --------------------------------------------------------------------------
    test_rows = load_jsonl(data / "test.jsonl")
    preds = correct_texts(trainer.model, tok, [r["input"] for r in test_rows], args.eval_bs, beams=1, max_len=args.max_len)
    report = score(test_rows, preds)
    (out / "test_report.json").write_text(json.dumps(report, indent=2))
    print("\n=== TEST (sentences never seen in training) ===")
    print(json.dumps(report, indent=2))
    print(f"\nCheckpoint saved to {out}")
    return 0



